import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { ELEMENTS, StyleProps, type LayoutNode } from "../../src/core/index.ts";
import {
  caseNames,
  EXPECTED_DIR,
  readStoredCase,
  renderCase,
  storedVersion,
} from "./render-case.ts";

/**
 * W-925 (D-065): stored pages from 0.x (schema 1 to 17 documents) still upgrade and render byte
 * for byte as they did before the 1.0 schema freeze. Expected output was rendered by 0.9.0
 * (commit 165f33a8) and is never regenerated by a test.
 */
describe("0.x pages render unchanged after the schema freeze (W-925)", () => {
  test("the corpus is not empty", () => {
    expect(caseNames().length).toBeGreaterThanOrEqual(10);
  });
  for (const name of caseNames()) {
    test(name, () => {
      const expected = JSON.parse(readFileSync(join(EXPECTED_DIR, `${name}.json`), "utf8")) as {
        html: string;
        css: string;
      };
      const actual = renderCase(name);
      expect(actual.html).toBe(expected.html);
      expect(actual.css).toBe(expected.css);
    });
  }
});

/** Layout schema each npm release wrote (from packages/emvb/package.json and schema/layout.ts at each version bump). */
const RELEASED_LAYOUT_SCHEMAS: Record<string, number> = {
  "0.1.0": 9,
  "0.2.0": 12,
  "0.2.1": 12,
  "0.3.0": 13,
  "0.4.0": 15,
  "0.5.0": 15,
  "0.6.0": 16,
  "0.7.0": 16,
  "0.8.0": 17,
  "0.9.0": 17,
};

/**
 * Element types added in 1.x (D-065: additive only). No 0.x page can hold them, so the 0.x
 * corpus can't either; each has its own render tests, named here.
 */
const ADDED_IN_1X: Record<string, string> = {
  "language-switcher": "1.0 (W-937): src/core/render/language-switcher.test.ts",
};

type Style = Record<string, unknown> & { motion?: Record<string, unknown> };

function usedKeys(names: string[]) {
  const types = new Set<string>();
  const styles = new Set<string>();
  const style = (value: unknown) => {
    if (!value || typeof value !== "object") return;
    for (const [key, inner] of Object.entries(value as Style)) {
      if (key === "motion" && inner && typeof inner === "object") {
        for (const part of Object.keys(inner)) styles.add(`motion.${part}`);
      } else styles.add(key);
    }
  };
  const layers = (owner: { style?: unknown; states?: unknown; devices?: unknown }) => {
    style(owner.style);
    for (const layer of [owner.states, owner.devices]) {
      for (const value of Object.values((layer ?? {}) as Record<string, unknown>)) style(value);
    }
  };
  const walk = (node: LayoutNode) => {
    types.add(node.type);
    layers(node);
    if (node.query) style(node.query.style);
    for (const child of (node as { children?: LayoutNode[] }).children ?? []) walk(child);
  };
  for (const name of names) {
    const { design, layout, templates } = readStoredCase(name);
    for (const doc of [layout, ...templates]) walk(doc.root);
    for (const cls of design.classes ?? []) layers(cls);
  }
  return { types, styles };
}

describe("the compatibility corpus covers the 1.0 contract (W-926)", () => {
  test("every case is accepted: no stored page from 0.x is rejected on read", () => {
    const rejected: string[] = [];
    for (const name of caseNames()) {
      try {
        readStoredCase(name);
      } catch (error) {
        rejected.push(String(error).slice(0, 200));
      }
    }
    expect(rejected).toEqual([]);
  });

  test("every released layout schema has a stored page", () => {
    const stored = new Set(caseNames().map(storedVersion));
    const missing = Object.entries(RELEASED_LAYOUT_SCHEMAS)
      .filter(([, schema]) => !stored.has(schema))
      .map(([release]) => release);
    expect(missing).toEqual([]);
  });

  test("every element type and style key appears in at least one case", () => {
    const { types, styles } = usedKeys(caseNames());
    const wantStyles = Object.keys(StyleProps.shape).flatMap((key) =>
      key === "motion"
        ? ["transition", "entrance", "scroll", "icon"].map((p) => `motion.${p}`)
        : [key],
    );
    expect(
      Object.keys(ELEMENTS).filter((type) => !types.has(type) && !(type in ADDED_IN_1X)),
    ).toEqual([]);
    expect(wantStyles.filter((key) => !styles.has(key))).toEqual([]);
  });
});
